parameters.jsCode:
// One item per uploaded file. The file is always stored under `document`.
const out = [];
for (const item of $input.all()) {
  const f = item.json;
  for (const [key, file] of Object.entries(item.binary ?? {})) {
    out.push({
      json: {
        source: 'Upload form',
        client_name: String(f['Your full name'] ?? '').trim(),
        client_email: String(f['Email address'] ?? '').trim().toLowerCase(),
        tax_year: String(f['Tax year'] ?? '').trim(),
        file_name: file.fileName ?? key,
        received_at: new Date().toISOString(),
      },
      binary: { document: file },
    });
  }
}
return out;

// One item per attachment. Small images (signatures, logos) are skipped.
function bytes(size) {
  const m = String(size ?? '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)?/i);
  if (!m) return Infinity;
  const unit = { b: 1, kb: 1e3, mb: 1e6, gb: 1e9 }[(m[2] || 'b').toLowerCase()] ?? 1;
  return parseFloat(m[1]) * unit;
}
const out = [];
for (const item of $input.all()) {
  const from = String(item.json.from ?? '');
  const m = from.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
  const name = m ? m[1].trim() : '';
  const email = (m ? m[2] : from).trim().toLowerCase();
  const year = String(item.json.subject ?? '').match(/\b(20\d\d)\b/);
  for (const [key, file] of Object.entries(item.binary ?? {})) {
    const mime = String(file.mimeType ?? '');
    if (mime.startsWith('image/') && bytes(file.fileSize) < 20000) continue;
    out.push({
      json: {
        source: 'Email',
        client_name: name,
        client_email: email,
        tax_year: year ? year[1] : '',
        file_name: file.fileName ?? key,
        received_at: new Date().toISOString(),
      },
      binary: { document: file },
    });
  }
}
return out;

// Drive files have no client details; the reviewer fills them in from the log.
return $input.all().map((item) => ({
  json: {
    source: 'Google Drive',
    client_name: '',
    client_email: '',
    tax_year: String(item.json.name ?? '').match(/\b(20\d\d)\b/)?.[1] ?? '',
    file_name: item.json.name ?? item.binary?.data?.fileName ?? 'drive-file',
    received_at: new Date().toISOString(),
  },
  binary: { document: item.binary.data },
}));

// multipart/form-data: any file fields, plus optional client_name, client_email, tax_year.
const out = [];
for (const item of $input.all()) {
  const body = item.json.body ?? {};
  for (const [key, file] of Object.entries(item.binary ?? {})) {
    out.push({
      json: {
        source: 'API',
        client_name: String(body.client_name ?? '').trim(),
        client_email: String(body.client_email ?? '').trim().toLowerCase(),
        tax_year: String(body.tax_year ?? '').trim(),
        file_name: file.fileName ?? key,
        received_at: new Date().toISOString(),
      },
      binary: { document: file },
    });
  }
}
return out;

// ============ EDIT YOUR SETTINGS HERE (keep the quotes) ============
const SETTINGS = {
  firm_name: 'Your Firm Name',
  api_url: 'http://localhost:8000',        // where the Tax Document API runs
  reviewer_email: 'review@yourfirm.com',   // who is told when a person should look
  sender_email: 'n8n@yourfirm.com',        // the address those emails come from
  min_confidence: 0.90,                    // below this, a person double-checks the form type
};
// ============ END OF SETTINGS ============

return $input.all().map((item, i) => ({
  json: {
    ...item.json,
    document_id: `${Date.now().toString(36)}-${i}-${Math.random().toString(36).slice(2, 7)}`,
    settings: SETTINGS,
  },
  binary: item.binary,
}));

// Turn an API error, an unreadable file or unsupported pages into a plain-English log entry.
// status 'failed': nothing could be read (the team is alerted). 'needs_review': pages to handle by hand.
const doc = $json.doc ?? $('Firm Settings').item.json;
const problem = $json.problem;
const status = Number($json.statusCode ?? 0);
const err = problem ?? $json.body?.error ?? {};
const byCode = {
  unsupported_media_type: 'This file type cannot be read. Please send a PDF or a picture (PNG, JPG, TIFF).',
  too_many_pages: 'The file has too many pages. Split it into smaller files.',
  unreadable_document: 'The document could not be read: it may be damaged, password-protected or blank.',
  no_forms: 'No text could be read from the file. It may be blank or a very poor scan.',
};
const byStatus = {
  400: 'The file was empty or the upload was incomplete. Ask for the file again.',
  401: 'n8n could not log in to the Tax Document API. Check the "Tax Document API key" credential.',
  413: 'The file is too large. Send files under the size limit, or one form per file.',
  415: byCode.unsupported_media_type,
  422: byCode.unreadable_document,
  429: 'Too many documents arrived at once. Re-send this file in a minute.',
  503: 'The AI models on the document server are not running. Start Ollama, then re-send this file.',
};
let reason;
let outcome = 'failed';
if (problem?.code === 'unsupported_pages') {
  outcome = 'needs_review';
  reason = `Page ${problem.pages} of this file is not one of the supported tax forms. It needs to be handled by hand.`;
} else if (problem?.code === 'missing_pages') {
  outcome = 'needs_review';
  reason = `No text could be read from page(s) ${problem.pages} of this file${problem.partial ? ' (the file was only partly converted)' : ''}. `
    + 'They may be blank, or a form on them was missed: check them by hand.';
} else if (problem) {
  reason = byCode[problem.code] ?? `The Tax Document API could not read this file: ${problem.message ?? problem.code}`;
} else if (!status) {
  reason = `n8n could not reach the Tax Document API at ${doc.settings.api_url}. Is the server running?`;
} else {
  reason = byStatus[status] ?? `Unexpected error from the Tax Document API (HTTP ${status}): ${err.message ?? 'no details'}`;
}

return {
  json: {
    record: {
      document_id: doc.document_id, received_at: doc.received_at, source: doc.source,
      client_name: doc.client_name, client_email: doc.client_email, file_name: doc.file_name,
      pages: problem?.pages ?? '', document_type: outcome === 'failed' ? 'failed' : 'unsupported', form_name: '',
      tax_year: doc.tax_year, confidence: 0, status: outcome, summary: reason, issues: reason,
      client_follow_ups: '', return_notes: '', extracted_fields: '', api_request_id: err.request_id ?? '',
    },
    settings: doc.settings,
  },
};

// Mask tax IDs, add rule-based review flags, and package one form for the assistant.
const { doc, form, pages, form_count } = $json;

function maskTins(value) {
  if (Array.isArray(value)) return value.map(maskTins);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => {
      const isTin = k === 'tin' || k === 'ssn' || k.endsWith('_ssn');
      return [k, isTin && typeof v === 'string' && v.length >= 4 ? `XXX-XX-${v.slice(-4)}` : maskTins(v)];
    }));
  }
  return value;
}

// Long transaction lists are summarised for the assistant (the log keeps every row).
function forAssistant(fields) {
  const rows = fields.transactions;
  if (!Array.isArray(rows) || rows.length <= 25) return fields;
  const byBox = {};
  for (const t of rows) {
    const b = (byBox[t.form_8949_box ?? '?'] ??= { sales: 0, proceeds: 0, cost_basis: 0, wash_sale_loss_disallowed: 0 });
    b.sales += 1;
    for (const k of ['proceeds', 'cost_basis', 'wash_sale_loss_disallowed']) b[k] = Math.round((b[k] + (t[k] ?? 0)) * 100) / 100;
  }
  return { ...fields, transactions: rows.slice(0, 10), transaction_summary: { total_sales: rows.length, by_form_8949_box: byBox, note: 'first 10 sales shown' } };
}

const flags = [];
if (form.classification.confidence < doc.settings.min_confidence) {
  flags.push(`Form type is uncertain (${Math.round(form.classification.confidence * 100)}% sure it is ${form.form_name}).`);
}
if (!form.text_layer) {
  flags.push('Scanned or photographed document: names and amounts were read by OCR; check them against the image.');
}
for (const w of form.validation.warnings) flags.push(`Extraction warning: ${w}`);
if (doc.tax_year && form.fields.tax_year && String(form.fields.tax_year) !== doc.tax_year) {
  flags.push(`Client said tax year ${doc.tax_year}, but the form says ${form.fields.tax_year}.`);
}
if (form_count > 1) flags.push(`One of ${form_count} forms in this file (page ${pages}).`);

const fields = maskTins(form.fields);
return {
  json: {
    action: 'review_document',
    query: doc.client_email,
    payload: {
      document_id: doc.document_id,
      client_name: doc.client_name,
      client_email: doc.client_email,
      file_name: doc.file_name,
      pages,
      document_type: form.document_type,
      form_name: form.form_name,
      confidence: form.classification.confidence,
      scanned: !form.text_layer,
      fields: forAssistant(fields),
      rule_flags: flags,
      api_request_id: $json.request_id,
    },
    doc,
    fields,
  },
};

// Combine extraction + review. The assistant can raise a review, never clear a rule flag.
const prepared = Object.fromEntries($('Prepare Review').all().map((p) => [p.json.payload.document_id, p.json]));

return $input.all().map((item) => {
  const { payload: p, doc, fields } = prepared[item.json.document_id];
  const review = item.json.review ?? {};
  const issues = [...p.rule_flags, ...(review.issues ?? [])];
  const needsReview = p.rule_flags.length > 0 || review.review_needed !== false;
  return {
    json: {
      record: {
        document_id: p.document_id, received_at: doc.received_at, source: doc.source,
        client_name: doc.client_name, client_email: doc.client_email, file_name: doc.file_name, pages: p.pages,
        document_type: p.document_type, form_name: p.form_name,
        tax_year: String(fields.tax_year ?? doc.tax_year ?? ''),
        confidence: Math.round(p.confidence * 1000) / 1000,
        status: needsReview ? 'needs_review' : 'ready',
        summary: review.summary ?? '',
        issues: issues.join('\n'),
        client_follow_ups: (review.client_follow_ups ?? []).join('\n'),
        return_notes: (review.return_notes ?? []).join('\n'),
        extracted_fields: JSON.stringify(fields),
        api_request_id: p.api_request_id ?? '',
      },
      settings: doc.settings,
    },
  };
});

// HTML-escape everything: document text is untrusted.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const list = (s) => s ? `<ul>${String(s).split('\n').map((l) => `<li>${esc(l)}</li>`).join('')}</ul>` : '<p>None</p>';
const r = $json.record;
const s = $json.settings;
const title = r.status === 'failed' ? 'Could not process a document' : 'A document needs review';
return {
  json: {
    to: s.reviewer_email,
    from: s.sender_email,
    subject: `[${s.firm_name}] ${title}: ${r.file_name} (${r.client_name || r.client_email || 'unknown client'})`,
    html: `
      <h2>${esc(title)}</h2>
      <p><b>Client:</b> ${esc(r.client_name)} ${esc(r.client_email)}<br>
         <b>File:</b> ${esc(r.file_name)} (via ${esc(r.source)})<br>
         <b>Form:</b> ${esc(r.form_name || r.document_type)} ${esc(r.tax_year)}<br>
         <b>Log id:</b> ${esc(r.document_id)}</p>
      <h3>Summary</h3><p>${esc(r.summary)}</p>
      <h3>What to check</h3>${list(r.issues)}
      <h3>Questions for the client</h3>${list(r.client_follow_ups)}
      <h3>Return preparation notes</h3>${list(r.return_notes)}
      <p style="color:#666">Tax IDs are masked. Full details are in the tax_document_log table.</p>`,
  },
};

