        "type": "string"
      }
    },
    "return_notes": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "summary",
    "review_needed",
    "issues",
    "client_follow_ups",
    "return_notes"
  ]
}

parameters.jsCode:
// Fail closed: if the assistant errored or returned nothing, a person reviews.
const entry = $('Sub-workflow Entry').first().json;
const out = $json.output;
const review = out && typeof out === 'object' ? out : {
  summary: 'The AI review was not available for this document.',
  review_needed: true,
  issues: [`AI review failed: ${$json.error?.message ?? $json.error ?? 'no output'}`],
  client_follow_ups: [],
  return_notes: [],
};
return [{ json: { document_id: entry.payload.document_id, review } }];

const email = $('Sub-workflow Entry').first().json.query;
if (!email) return [{ json: { response: 'No client email is known for this document, so there is no history to check.' } }];
const rows = $input.all().map((i) => i.json).filter((r) => r.document_id);
if (!rows.length) return [{ json: { response: `No earlier documents on file for ${email}.` } }];
const lines = rows.map((r) =>
  `- ${String(r.received_at ?? '').slice(0, 10)}: ${r.form_name || r.document_type} ${r.tax_year || ''} (${r.file_name}, status ${r.status})`);
return [{ json: { response: `Earlier documents for ${email} (newest first):\n${lines.join('\n')}` } }];

// Static reference so the assistant does not rely on memory for codes and line numbers.
// Line numbers follow the 2025 Form 1040 and its schedules: confirm against the current IRS instructions.
const REF = {
  'w-2': {
    where: 'Box 1 -> Form 1040 line 1a. Box 2 -> line 25a. Boxes 3-6 are Social Security / Medicare (not entered as income). Box 12 code W also needs Form 8889; code D/E/G/S are retirement deferrals; box 13 "Retirement plan" affects the IRA deduction.',
    codes: { A: 'Uncollected Social Security tax on tips', B: 'Uncollected Medicare tax on tips', C: 'Taxable cost of group-term life insurance over $50,000 (already in box 1)', D: '401(k) elective deferrals', E: '403(b) elective deferrals', F: '408(k)(6) SARSEP deferrals', G: '457(b) deferrals', H: '501(c)(18)(D) plan deferrals', J: 'Nontaxable sick pay', K: '20% excise tax on excess golden parachute payments', L: 'Substantiated employee business expense reimbursements', M: 'Uncollected Social Security tax on group-term life (former employees)', N: 'Uncollected Medicare tax on group-term life (former employees)', P: 'Excludable moving expense reimbursements (armed forces)', Q: 'Nontaxable combat pay', R: 'Employer contributions to an Archer MSA', S: '408(p) SIMPLE contributions', T: 'Adoption benefits (Form 8839)', V: 'Income from exercise of nonstatutory stock options (already in box 1)', W: 'Employer HSA contributions, including cafeteria-plan amounts (Form 8889)', Y: 'Section 409A deferrals', Z: 'Income under a 409A plan that fails 409A (subject to extra tax)', AA: 'Designated Roth contributions to 401(k)', BB: 'Designated Roth contributions to 403(b)', DD: 'Cost of employer-sponsored health coverage (informational, not taxable)', EE: 'Designated Roth contributions to governmental 457(b)', FF: 'Qualified small employer HRA benefits', GG: 'Income from qualified equity grants under 83(i)', HH: 'Aggregate deferrals under 83(i) elections' },
  },
  '1099-nec': { where: 'Box 1 -> Schedule C (business income, also Schedule SE) or Schedule 1 line 8 if not a trade or business. Box 4 -> Form 1040 line 25b.' },
  '1099-misc': { where: 'Box 1 rents and box 2 royalties -> Schedule E. Box 3 other income -> Schedule 1 line 8. Box 6 and box 10 usually belong to a business (Schedule C). Box 4 -> Form 1040 line 25b.' },
  '1099-int': { where: 'Box 1 (and box 3) -> Schedule B, then Form 1040 line 2b. Box 8 tax-exempt interest -> line 2a. Box 2 early withdrawal penalty -> Schedule 1 line 18. Box 4 -> line 25b.' },
  '1099-div': { where: 'Box 1a -> Schedule B / Form 1040 line 3b. Box 1b qualified dividends -> line 3a. Box 2a -> Schedule D line 13 (or line 7 directly if no Schedule D is needed). Box 5 -> Form 8995 (QBI). Box 7 foreign tax -> Schedule 3 line 1 or Form 1116. Box 4 -> line 25b.' },
  '1099-r': {
    where: 'IRA distributions -> Form 1040 lines 4a/4b; pensions and annuities -> lines 5a/5b. Box 4 -> line 25b. Early distributions (code 1) may owe the 10% additional tax on Form 5329.',
    codes: { 1: 'Early distribution, no known exception', 2: 'Early distribution, exception applies', 3: 'Disability', 4: 'Death', 5: 'Prohibited transaction', 6: 'Section 1035 exchange', 7: 'Normal distribution', 8: 'Excess contributions taxable in the current year', 9: 'Cost of current life insurance protection', A: 'May be eligible for 10-year tax option', B: 'Designated Roth account distribution', D: 'Annuity payments from nonqualified annuities', E: 'Distribution under EPCRS', F: 'Charitable gift annuity', G: 'Direct rollover to a qualified plan or IRA (usually not taxable)', H: 'Direct rollover of a designated Roth account to a Roth IRA', J: 'Early distribution from a Roth IRA', K: 'Distribution of IRA assets without a readily available market value', L: 'Loan treated as a distribution', M: 'Qualified plan loan offset', N: 'Recharacterized IRA contribution, same year', P: 'Excess contributions taxable in the prior year', Q: 'Qualified distribution from a Roth IRA', R: 'Recharacterized IRA contribution, prior year', S: 'Early distribution from a SIMPLE IRA in the first 2 years, no known exception', T: 'Roth IRA distribution, exception applies', U: 'Dividend from an ESOP', W: 'Charges for qualified long-term care insurance contracts' },
  },
  '1099-g': { where: 'Box 1 unemployment -> Schedule 1 line 7. Box 2 state refund -> Schedule 1 line 1, only if state tax was itemized on the prior-year Schedule A. Box 4 -> Form 1040 line 25b.' },
  'ssa-1099': { where: 'Box 5 -> Form 1040 line 6a; the taxable part (worksheet) -> line 6b. Box 6 -> line 25b. Medicare premiums can be a Schedule A medical expense.' },
  '1098': { where: 'Box 1 (and box 6 points) -> Schedule A line 8a if itemizing. Box 5 mortgage insurance premiums: check whether deductible for the tax year. Box 2 and box 11 help apply the mortgage debt limit.' },
  '1098-t': { where: 'Boxes 1 and 5 -> Form 8863 (American Opportunity / Lifetime Learning credits). Box 5 more than box 1 can mean taxable scholarship income.' },
  '1098-e': { where: 'Box 1 -> Schedule 1 line 21 (student loan interest deduction, income limits apply).' },
  '1099-b': { where: 'Each sale -> Form 8949: short-term in Part I (box A: basis reported to IRS, B: not reported, C: no 1099-B), long-term in Part II (D, E, F); totals -> Schedule D. Box A/D sales with no adjustments may go straight to Schedule D lines 1a/8a. Box 1g wash sale loss disallowed -> Form 8949 column (g), code W. Box 4 -> Form 1040 line 25b.' },
  '1099-k': { where: 'Box 1a gross payments are not automatically income: business sales -> Schedule C, rentals -> Schedule E, personal items sold at a gain -> Form 8949 / Schedule D; personal items sold at a loss, or amounts reported in error, are reported on Schedule 1 lines 8z and 24z so they net to zero. Box 4 -> Form 1040 line 25b.' },
  '1095-a': { where: 'Part III monthly columns -> Form 8962 (premium tax credit): A enrollment premiums, B second lowest cost silver plan premium, C advance payments. Excess advance credit to repay -> Schedule 2; net premium tax credit -> Schedule 3. Coverage households and policy dates come from Parts I-II.' },
  'k-1': {
    where: 'Schedule K-1 (1065): box 1 -> Schedule E Part II; box 2/3 rental -> Schedule E (passive rules, Form 8582); box 4 guaranteed payments -> Schedule E and Schedule SE; box 5/6 -> Schedule B; box 9a -> Schedule D; box 14 -> Schedule SE; box 20 code Z -> Form 8995 (QBI). Box 19 distributions are not income but reduce basis.',
    codes: { '14A': 'Net earnings (loss) from self-employment', '14B': 'Gross farming or fishing income', '14C': 'Gross nonfarm income', '19A': 'Cash and marketable securities distributed', '19B': 'Distribution subject to section 737', '19C': 'Distribution of other property', '20A': 'Investment income', '20B': 'Investment expenses', '20N': 'Business interest expense', '20Z': 'Section 199A (QBI) information' },
  },
};
const ALIASES = { '1095a': '1095-a', 'w2': 'w-2', 'k1': 'k-1', 'schedule k-1': 'k-1', 'ssa1099': 'ssa-1099', 'ssa 1099': 'ssa-1099' };

const q = String($json.query ?? '').toLowerCase();
const formKey = Object.keys(REF).sort((a, b) => b.length - a.length)
  .find((k) => q.includes(k) || q.replace(/[\s-]/g, '').includes(k.replace(/-/g, '')))
  ?? Object.entries(ALIASES).find(([a]) => q.includes(a))?.[1];
if (!formKey) {
  return [{ json: { response: `No reference for "${$json.query}". Known forms: ${Object.keys(REF).join(', ')}.` } }];
}
const ref = REF[formKey];
const lines = [`${formKey.toUpperCase()}: ${ref.where}`];
// Drop the form name first, or "W-2" and "1099-R" would read as codes W and R.
const codePart = String($json.query).toUpperCase()
  .replace(/\b(FORM|SCHEDULE|SSA-?1099|W-?2|K-?1|1099-?[A-Z]+|1098-?[A-Z]?|BOX|CODES?)\b/g, ' ');
const tokens = codePart.match(/\b\d{0,2}[A-Z]{1,2}\b|\b\d{1,2}\b/g) ?? [];
// Try each token, and box numbers joined with the code after them ("20 Z" -> "20Z").
const keys = [...tokens, ...tokens.slice(1).map((t, i) => /^\d+$/.test(tokens[i]) ? tokens[i] + t : null).filter(Boolean)];
const seen = new Set();
for (const t of keys) {
  const key = ref.codes?.[t] ? t : t.replace(/^\d+/, '');
  if (ref.codes?.[key] && !seen.has(key)) {
    seen.add(key);
    lines.push(`Code ${key}: ${ref.codes[key]}`);
  }
}
return [{ json: { response: lines.join('\n') } }];

// One item per form found in the file. Forms that were not extracted (pages that are not a
// supported form, or a file the API could not read) are routed to Explain Failure, and so are
// pages no text was read from (blank, failed or unreadable), as one item per file.
// Repeated copies of a form (W-2 Copy C, Copy 2) are skipped: the API marks them `duplicate`.
const out = [];
$input.all().forEach((item, i) => {
  const doc = $('Firm Settings').itemMatching(i).json;
  const data = item.json.body.data;
  const file = data.files[0];
  if (file.status === 'failed') {
    out.push({ json: { kind: 'problem', doc, problem: { ...file.error, request_id: data.request_id } }, pairedItem: { item: i } });
    return;
  }
  const forms = file.forms.filter((f) => f.status !== 'duplicate');
  if (!forms.length) {
    out.push({ json: { kind: 'problem', doc, problem: { code: 'no_forms', message: 'No text could be read from the file.', request_id: data.request_id } }, pairedItem: { item: i } });
    return;
  }
  for (const form of forms) {
    const id = forms.length > 1 ? `${doc.document_id}-${form.index + 1}` : doc.document_id;
    const pages = form.pages.join(', ');
    const common = { doc: { ...doc, document_id: id }, pages, form_count: forms.length, request_id: data.request_id };
    if (form.status === 'unsupported') {
      out.push({ json: { kind: 'problem', ...common, problem: { code: 'unsupported_pages', pages, request_id: data.request_id } }, pairedItem: { item: i } });
    } else {
      out.push({ json: { kind: 'form', ...common, form }, pairedItem: { item: i } });
    }
  }
  const missing = file.document?.missing_pages ?? [];
  if (missing.length) {
    const pages = missing.join(', ');
    out.push({ json: { kind: 'problem', doc: { ...doc, document_id: `${doc.document_id}-unread` }, pages, request_id: data.request_id,
      problem: { code: 'missing_pages', pages, partial: file.document.conversion === 'partial', request_id: data.request_id } }, pairedItem: { item: i } });
  }
});
return out;

// Team alert for pipeline errors, in three formats. Inputs: Explain Failure records (only
// status 'failed' alerts; pages to handle by hand go to the reviewer email instead) and the
// Error Trigger payload when the workflow itself crashed.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const flat = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();  // WhatsApp template parameters reject newlines
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const r = j.record;
  if (r && r.status !== 'failed') continue;
  const firm = j.settings?.firm_name ?? j.workflow?.name ?? 'Tax pipeline';
  const err = j.execution?.error ?? j.trigger?.error ?? {};
  const title = r ? `[${firm}] Could not process a document` : `[${firm}] Tax pipeline error`;
  const fields = r
    ? [['File', `${r.file_name} (via ${r.source})`], ['Client', r.client_name || r.client_email || 'unknown'],
       ['Problem', r.summary], ['Log id', r.document_id]]
    : [['Failed step', j.execution?.lastNodeExecuted ?? 'trigger'], ['Problem', err.message ?? 'unknown error'],
       ['Execution', j.execution?.url ?? j.execution?.id ?? 'n/a']];
  out.push({ json: {
    slack_text: [`*${esc(title)}*`, ...fields.map(([k, v]) => `*${k}:* ${esc(v)}`)].join('\n'),
    telegram_html: [`<b>${esc(title)}</b>`, ...fields.map(([k, v]) => `<b>${k}:</b> ${esc(v)}`)].join('\n'),
    whatsapp_text: flat([title, ...fields.map(([k, v]) => `${k}: ${v}`)].join(' | ')).slice(0, 900),
  } });
}
return out;
